validator:
function validate(input) {
  const [{ Drivers = [], Rides = [], AcceptedRides = [] }] = input;
  const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d);
  const drivers = new Set(), rides = new Set(), accepted = new Set();
  for (const [id, date] of Drivers) {
    if (id === null || date === null) return 'Drivers rows may not contain null.';
    if (drivers.has(id)) return `driver_id ${id} appears twice in Drivers.`;
    if (!isDate(date)) return 'Dates must look like 2020-01-31.';
    drivers.add(id);
  }
  for (const row of Rides) {
    if (row.some((v) => v === null)) return 'Rides rows may not contain null.';
    if (rides.has(row[0])) return `ride_id ${row[0]} appears twice in Rides.`;
    if (!isDate(row[2])) return 'Dates must look like 2020-01-31.';
    rides.add(row[0]);
  }
  for (const row of AcceptedRides) {
    if (row.some((v) => v === null)) return 'AcceptedRides rows may not contain null.';
    const [id, , distance, duration] = row;
    if (accepted.has(id)) return `ride_id ${id} appears twice in AcceptedRides.`;
    if (!rides.has(id)) return `Accepted ride ${id} is missing from Rides.`;
    if (distance < 0 || duration < 0) return 'Distances and durations may not be negative.';
    accepted.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const pool = ['2019-12-31', '2020-01-01', '2020-02-29', '2020-03-31', '2020-04-01', '2020-06-15', '2020-09-30', '2020-10-01', '2020-11-11', '2020-12-31', '2021-01-01'];
  const date = () => small ? pick(pool) : `${2019 + Math.floor(rand() * 3)}-${String(1 + Math.floor(rand() * 12)).padStart(2, '0')}-${String(1 + Math.floor(rand() * 28)).padStart(2, '0')}`;
  const driverCount = small ? Math.floor(rand() * 4) : 300;
  const rideCount = small ? Math.floor(rand() * 9) : 2000;
  const Drivers = [], Rides = [], AcceptedRides = [];
  for (let id = 1; id <= driverCount; id++) Drivers.push([id, date()]);
  for (let id = 1; id <= rideCount; id++) {
    Rides.push([id, 1 + Math.floor(rand() * (small ? 5 : 300)), date()]);
    if (rand() < 0.7) AcceptedRides.push([id, 1 + Math.floor(rand() * Math.max(driverCount, 1)), Math.floor(rand() * (small ? 20 : 200)), Math.floor(rand() * (small ? 20 : 150))]);
  }
  return [{ Drivers, Rides, AcceptedRides }];
}
